import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.BU4O3IzQ.js";const d=JSON.parse('{"title":"AI 动态 · 2026-08-02","description":"","frontmatter":{"title":"AI 动态 · 2026-08-02","date":"2026-08-02T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-02.md","filePath":"news/2026-08/ai-news-2026-08-02.md","lastUpdated":1786092171000}'),s={name:"news/2026-08/ai-news-2026-08-02.md"};function i(o,e,c,l,p,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-02" tabindex="-1">AI 动态 · 2026-08-02 <a class="header-anchor" href="#ai-动态-·-2026-08-02" aria-label="Permalink to &quot;AI 动态 · 2026-08-02&quot;">​</a></h1><blockquote><p>截至 2026-08-02。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="waic-收官圆桌-数百家机器人刷屏背后-ai-究竟重写了什么" tabindex="-1">WAIC 收官圆桌：数百家机器人刷屏背后，AI 究竟重写了什么？ <a class="header-anchor" href="#waic-收官圆桌-数百家机器人刷屏背后-ai-究竟重写了什么" aria-label="Permalink to &quot;WAIC 收官圆桌：数百家机器人刷屏背后，AI 究竟重写了什么？&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://static001.infoq.cn/resource/image/e9/29/e92af57dcf3920b2006c9610f6dde429.png" alt="配图"></p><p>WAIC 2026 收官圆桌邀请四位一线观察者，从学术、产研、创业与资本视角，检验大模型、Agent、具身智能等热词在真实工作流与商业化中的实际进展。讨论指出，具身智能尚未实现稳定工业级作业，本地智能体与新模型范式正加速验证真实需求，Scaling Law 瓶颈下扩散语言模型等基础路线获创业关注。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/D9d8F0SUE4gCrXbbyU8N?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="用了多年-react-remix-终于-叛变-了-3-0-版本彻底重写" tabindex="-1">用了多年 React，Remix 终于“叛变”了：3.0 版本彻底重写 <a class="header-anchor" href="#用了多年-react-remix-终于-叛变-了-3-0-版本彻底重写" aria-label="Permalink to &quot;用了多年 React，Remix 终于“叛变”了：3.0 版本彻底重写&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://static001.infoq.cn/resource/image/d9/7f/d981ab0289beyye22dc5ce06yyb5c77f.jpg" alt="配图"></p><p>Remix 3 beta 预览版发布，从底层重新构建，将项目从 React 迁移到 Web 平台原生基础能力之上。新版本定位为完整全栈体系，路由基于 Fetch API，移除 React 运行时，采用基于 Preact 的分支版本和命令式模型，并引入“unbundling”理念。社区评价明显分化，有观察者认为这标志着从函数式编程向命令式编程的钟摆正在摆回。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/s8IA8KgdrizgCEsQAOXr?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="nvidia-vera-rubin-正式登场-从芯片卷到电网-只为压低每一个-token-的成本" tabindex="-1">NVIDIA Vera Rubin 正式登场：从芯片卷到电网，只为压低每一个 Token 的成本 <a class="header-anchor" href="#nvidia-vera-rubin-正式登场-从芯片卷到电网-只为压低每一个-token-的成本" aria-label="Permalink to &quot;NVIDIA Vera Rubin 正式登场：从芯片卷到电网，只为压低每一个 Token 的成本&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://static001.infoq.cn/resource/image/75/2c/759c151c35140d3ab71fc4173c382b2c.png" alt="配图"></p><p>NVIDIA Vera Rubin NVL72 加速量产，CoreWeave、Google Cloud、Microsoft Azure 等合作伙伴机架已投入运行。平台从芯片到电网进行全栈协同设计，七款芯片和五种机架托盘深度协同，供应链覆盖 30 国 350+ 工厂。CoreWeave 针对 DeepSeek-R1 的基准测试显示，每兆瓦吞吐量比 Grace Blackwell NVL72 提升 10 倍。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/3gb6NlxK6c0A9or5Zfbt?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="_92-工程师都在用-ai-后-uber-开始给-ai-限额-了" tabindex="-1">92% 工程师都在用 AI 后，Uber 开始给 AI “限额”了 <a class="header-anchor" href="#_92-工程师都在用-ai-后-uber-开始给-ai-限额-了" aria-label="Permalink to &quot;92% 工程师都在用 AI 后，Uber 开始给 AI “限额”了&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://static001.infoq.cn/resource/image/d3/09/d313b0f83fe271d522d670a1c16e5409.jpg" alt="配图"></p><p>Uber 的“零增长技术栈”将容量增长与业务需求增长解耦，通过自动化运行时优化和严格的 AI 生命周期管理降低开销。92% 工程师每月使用 AI Agent，31% 新代码由 AI 编写，但 AI 相关成本自 2024 年以来增长六倍，单个开发者月度成本达 2000 美元。Uber 正从无限制采用转向限额管理。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/Iu2dhFs8JiFqoUGuXJ4m?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="google-earth-内置-ai-图像生成器引发误导信息担忧" tabindex="-1">Google Earth 内置 AI 图像生成器引发误导信息担忧 <a class="header-anchor" href="#google-earth-内置-ai-图像生成器引发误导信息担忧" aria-label="Permalink to &quot;Google Earth 内置 AI 图像生成器引发误导信息担忧&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://platform.theverge.com/wp-content/uploads/sites/2/2026/07/Dream-House.mp4_snapshot_00.11.422.jpg?quality=90&amp;strip=all&amp;crop=0%2C3.4613147178592%2C100%2C93.077370564282&amp;w=1200" alt="配图"></p><p>Google Earth 推出的 AI 图像生成功能可基于卫星、航拍和 3D 影像生成现实扭曲图像，被迅速用于生成误导性内容，如墨西哥边境难民和加沙医院炸弹坑图像。尽管 Google 声称所有图像均含 SynthID 数字水印，但批评者仍担忧其传播虚假信息的风险。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/973764/google-earth-ai-satellite-images" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="esengine-deepseek-reasonix-终端里的-deepseek-原生-ai-编程代理" tabindex="-1">esengine/DeepSeek-Reasonix：终端里的 DeepSeek 原生 AI 编程代理 <a class="header-anchor" href="#esengine-deepseek-reasonix-终端里的-deepseek-原生-ai-编程代理" aria-label="Permalink to &quot;esengine/DeepSeek-Reasonix：终端里的 DeepSeek 原生 AI 编程代理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">esengine/DeepSeek-Reasonix</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://opengraph.githubassets.com/1/esengine/DeepSeek-Reasonix" alt="配图"></p><p>DeepSeek-Reasonix 是一个面向终端的 DeepSeek 原生 AI 编程代理，围绕前缀缓存稳定性设计，可长期保持运行。该项目针对 DeepSeek 模型特性优化，适合在终端环境中持续辅助编码任务。</p><p class="news-entry-source"><a href="https://github.com/esengine/DeepSeek-Reasonix" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="panniantong-agent-reach-让-ai-代理读取全网-零-api-费用" tabindex="-1">Panniantong/Agent-Reach：让 AI 代理读取全网，零 API 费用 <a class="header-anchor" href="#panniantong-agent-reach-让-ai-代理读取全网-零-api-费用" aria-label="Permalink to &quot;Panniantong/Agent-Reach：让 AI 代理读取全网，零 API 费用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Panniantong/Agent-Reach</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://opengraph.githubassets.com/1/Panniantong/Agent-Reach" alt="配图"></p><p>Agent-Reach 通过一个 CLI 让 AI 代理读取和搜索 Twitter、Reddit、YouTube、GitHub、Bilibili、小红书等平台内容，无需支付 API 费用。该项目为代理提供互联网视野，适合需要跨平台信息获取的 Agent 应用。</p><p class="news-entry-source"><a href="https://github.com/Panniantong/Agent-Reach" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="lyogavin-airllm-单张-4gb-gpu-运行-70b-模型推理" tabindex="-1">lyogavin/airllm：单张 4GB GPU 运行 70B 模型推理 <a class="header-anchor" href="#lyogavin-airllm-单张-4gb-gpu-运行-70b-模型推理" aria-label="Permalink to &quot;lyogavin/airllm：单张 4GB GPU 运行 70B 模型推理&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">lyogavin/airllm</span><time datetime="2026-08-02">2026-08-02</time></p><p><img src="https://opengraph.githubassets.com/1/lyogavin/airllm" alt="配图"></p><p>AirLLM 项目实现了在单张 4GB GPU 上进行 70B 参数模型的推理，大幅降低了大型语言模型的硬件门槛。该项目通过优化推理策略，使资源受限环境也能运行大规模模型，对个人开发者和边缘计算场景具有实用价值。</p><p class="news-entry-source"><a href="https://github.com/lyogavin/airllm" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-代码搜索大小写折叠优化-单核速度超-45-gib-s" tabindex="-1">GitHub 代码搜索大小写折叠优化：单核速度超 45 GiB/s <a class="header-anchor" href="#github-代码搜索大小写折叠优化-单核速度超-45-gib-s" aria-label="Permalink to &quot;GitHub 代码搜索大小写折叠优化：单核速度超 45 GiB/s&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">GitHub Blog</span><time datetime="2026-08-02">2026-08-02</time></p><p>GitHub 博客分享了代码搜索中大小写折叠（case-folding）的优化技术，通过无分支循环和字节空间算术，在单核上实现了超过 45 GiB/s 的处理速度。该技术显著提升了代码搜索性能，对大规模代码库的检索效率有重要影响。</p><p class="news-entry-source"><a href="https://github.blog/engineering/architecture-optimization/dont-stop-early-case-folding-source-code-at-memory-speed/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const g=a(s,[["render",i]]);export{d as __pageData,g as default};
